import sys

data = sys.stdin.read().split()
n, k = int(data[0]), int(data[1])
m = [int(x) for x in data[2:2 + k]]
if n <= 5000:
    cities = range(1, n + 1)
else:
    ms = sorted(m)
    cities = {1, n}
    for a, b in zip(ms, ms[1:]):
        cities.add((a + b) // 2)
        cities.add((a + b + 1) // 2)
best = 0
for c in cities:
    best = max(best, min(abs(c - t) for t in m))
print(best)

